/* @lc app=leetcode id=3562 lang=kotlin */ class Solution { fun cv(a: IntArray, b: IntArray): IntArray = IntArray(a.size) { t -> (0..t).maxOf { a[it] + b[t - it] } } fun maxProfit(n: Int, present: IntArray, future: IntArray, hierarchy: Array<IntArray>, budget: Int): Int = hierarchy.groupBy({ it[0] }, { it[1] }).let { g -> generateSequence(listOf(1)) { f -> f.flatMap { g[it].orEmpty() }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> HashMap<Int, Array<IntArray>>().also { dp -> order.forEach { v -> dp[v] = Array(2) { p -> (present[v - 1] / (1 + p)).let { cost -> g[v].orEmpty().let { ch -> ch.fold(IntArray(budget + 1)) { acc, c -> cv(acc, dp[c]!![0]) }.let { no -> ch.fold(IntArray(budget + 1)) { acc, c -> cv(acc, dp[c]!![1]) }.let { yes -> IntArray(budget + 1) { b -> maxOf(no[b], if (b >= cost) yes[b - cost] + future[v - 1] - cost else Int.MIN_VALUE / 4) } } } } } } } }[1]!![0][budget] } } }